import * as T from 'three';
import {GLTFLoader} from '/simulations/vendor/loaders/GLTFLoader.js';
import {OrbitControls} from '/simulations/vendor/OrbitControls.js';
import {sandboxWheel} from '/simulations/vendor/sandbox-camera.mjs';
const notes={faceted:'Crisp bronze planes and a compact silhouette. Closest to the current character.',peg:'A turned wooden body with painted bands. Simple, warm, and readable in a crowd.',toy:'Broad shoulders, rounded blocks, and sturdy limbs. Built for clear marching and shield poses.',chibi:'Oversized helmet and face, tiny legs, and a generous shield. The most expressive proportions.',clay:'Soft, rounded masses and a handmade feel. Movement would need to preserve that softness.',voxel:'Square limbs, a stepped shield, and a block crest. Strong construction rhythm at small sizes.',paper:'Thin layered shapes and a folded cape. Charming from the front; less readable edge-on.',miniature:'Longer legs, smaller head, and finer equipment. More natural proportions, subtler at a distance.'};
const styles=await fetch('/greek-lineup-assets/styles.json').then(r=>r.json());
const lineup=document.querySelector('#lineup'),position=document.querySelector('#position');let index=0,lockedUntil=0;
const viewers=new Map();
function themeColor(name,fallback){return getComputedStyle(document.documentElement).getPropertyValue(name).trim()||fallback;}
window.addEventListener('app-style-change',()=>{for(const v of viewers.values())v.updateTheme?.();});
styles.forEach((s,i)=>{const section=document.createElement('section');section.className='study';section.dataset.index=i;section.setAttribute('aria-label',s.name);section.innerHTML=`<div class="shot" aria-label="${s.name} Blender close-up"><span class="shot-tag">${String(i+1).padStart(2,'0')} / BLENDER MOCKUP<br><small>Static · unrigged</small></span><button class="shot-nav previous" aria-label="Previous style, left" ${i===0?'disabled':''}>←</button><button class="shot-nav next" aria-label="Next style, right" ${i===styles.length-1?'disabled':''}>→</button><span class="shot-help">Drag to orbit · scroll to zoom</span></div><article class="review-card"><h2>${s.name}</h2><p>${notes[s.id]}</p></article>`;lineup.append(section);});
const sections=[...lineup.children];
function update(){position.textContent=`${index+1} / ${styles.length}`;load(index);}
function go(delta){const next=Math.max(0,Math.min(styles.length-1,index+delta));if(next===index)return;index=next;lockedUntil=performance.now()+500;lineup.scrollTo({left:index*lineup.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});update();}
lineup.querySelectorAll('.previous').forEach(b=>b.onclick=()=>go(-1));lineup.querySelectorAll('.next').forEach(b=>b.onclick=()=>go(1));document.querySelector('#fit').onclick=()=>viewers.get(index)?.fit();
window.addEventListener('keydown',e=>{if(['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))return;if(e.key==='ArrowRight'||e.key==='PageDown'){e.preventDefault();go(1);}if(e.key==='ArrowLeft'||e.key==='PageUp'){e.preventDefault();go(-1);}});
let wheelTime=0;lineup.addEventListener('wheel',e=>{if(e.target.closest('.shot'))return;if(Math.abs(e.deltaY)<2)return;e.preventDefault();if(performance.now()-wheelTime>450){wheelTime=performance.now();go(Math.sign(e.deltaY));}},{passive:false});
lineup.addEventListener('scroll',()=>{if(performance.now()<lockedUntil)return;const next=Math.max(0,Math.min(styles.length-1,Math.round(lineup.scrollLeft/lineup.clientWidth)));if(next!==index){index=next;update();}},{passive:true});
new ResizeObserver(()=>lineup.scrollTo({left:index*lineup.clientWidth,behavior:'instant'})).observe(lineup);
async function load(i){if(viewers.has(i))return;viewers.set(i,{});const host=sections[i].querySelector('.shot');try{
const renderer=new T.WebGLRenderer({antialias:true,alpha:false});renderer.setPixelRatio(Math.min(devicePixelRatio,1.5));renderer.shadowMap.enabled=true;renderer.shadowMap.type=T.PCFSoftShadowMap;renderer.toneMapping=T.ACESFilmicToneMapping;host.prepend(renderer.domElement);
const scene=new T.Scene();scene.background=new T.Color('#e8e2cc');scene.fog=new T.Fog('#e8e2cc',7,20);scene.add(new T.HemisphereLight('#fff6df','#73806a',2.1));const sun=new T.DirectionalLight('#fff1d6',3);sun.position.set(-3,6,4);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-3;sun.shadow.camera.right=3;sun.shadow.camera.top=4;sun.shadow.camera.bottom=-3;sun.shadow.normalBias=.02;scene.add(sun);
const floor=new T.Mesh(new T.PlaneGeometry(100,100),new T.MeshStandardMaterial({color:'#e8e2cc',roughness:1}));floor.rotation.x=-Math.PI/2;floor.position.y=-.12;floor.receiveShadow=true;scene.add(floor);
const base=new T.Mesh(new T.CylinderGeometry(.88,.92,.10,6),new T.MeshStandardMaterial({color:'#c9b890',roughness:.9}));base.position.y=-.055;base.receiveShadow=true;scene.add(base);
const camera=new T.PerspectiveCamera(33,1,.01,100),orbit=new OrbitControls(camera,renderer.domElement);orbit.mouseButtons={LEFT:T.MOUSE.ROTATE,MIDDLE:T.MOUSE.ROTATE,RIGHT:T.MOUSE.PAN};orbit.touches={ONE:T.TOUCH.ROTATE,TWO:T.TOUCH.DOLLY_PAN};orbit.minDistance=2;orbit.maxDistance=14;orbit.maxPolarAngle=Math.PI*.48;
renderer.domElement.addEventListener('wheel',e=>{e.preventDefault();e.stopImmediatePropagation();sandboxWheel(T,camera,orbit,e);},{capture:true,passive:false});
function fit(){orbit.target.set(0,1.12,0);const dist=Math.max(5.8,2.25/(2*Math.tan(33*Math.PI/360)*camera.aspect));camera.position.copy(orbit.target).add(new T.Vector3(1.7,1.1,6).normalize().multiplyScalar(dist));orbit.update();}
new ResizeObserver(()=>{const w=host.clientWidth,h=host.clientHeight;if(!w||!h)return;renderer.setSize(w,h);const insetSpace=0;renderer.setViewport(0,0,w,h-insetSpace);camera.aspect=w/(h-insetSpace);camera.updateProjectionMatrix();fit();}).observe(host);
const gltf=await new GLTFLoader().loadAsync(`/greek-lineup-assets/${styles[i].id}.glb`);gltf.scene.traverse(o=>{if(o.isMesh){o.castShadow=true;o.receiveShadow=true;}});scene.add(gltf.scene);fit();function updateTheme(){const color=themeColor('--app-canvas','#f4eddf');scene.background.set(color);scene.fog.color.set(color);floor.material.color.set(color);base.material.color.set(themeColor('--app-paper','#fffaf0'));}updateTheme();viewers.set(i,{renderer,scene,camera,fit,updateTheme});
}catch(e){host.insertAdjacentHTML('beforeend','<p class="load-error">This model could not load. Refresh to retry.</p>');console.error(e);}}
function frame(){const v=viewers.get(index);if(v?.renderer&&!document.hidden)v.renderer.render(v.scene,v.camera);requestAnimationFrame(frame);}update();frame();

const toolbar=document.querySelector("#lineup-toolbar");function dockSettings(){const b=document.querySelector("#app-settings-toggle");if(b&&b.parentElement!==toolbar)toolbar.append(b);}new MutationObserver(dockSettings).observe(document.body,{childList:true,subtree:true});dockSettings();
